import { ProxmoxNode, ProxmoxVm, ProxmoxStorage, ProxmoxTelemetry } from '../types.js';

export interface ParsedPveExporterData {
  nodes: ProxmoxNode[];
  vms: ProxmoxVm[];
  storages: ProxmoxStorage[];
  metricDefinitions: { metric: string; help: string; type: string; count: number }[];
  rawText: string;
  clusterName: string;
}

/**
 * Parses Prometheus exposition text format generated by pve_exporter / Prometheus Proxmox exporter.
 */
export function parsePveExporterText(rawText: string, fallbackNodeName?: string): ParsedPveExporterData {
  const lines = rawText.split('\n');

  // Metadata stores
  const metricHelps: Record<string, string> = {};
  const metricTypes: Record<string, string> = {};
  const metricCounts: Record<string, number> = {};

  // Node records
  const nodesMap = new Map<string, Partial<ProxmoxNode>>();
  // VM records (keyed by "qemu/100" or "lxc/200")
  const vmsMap = new Map<string, Partial<ProxmoxVm>>();
  // Storage records
  const storagesMap = new Map<string, Partial<ProxmoxStorage>>();

  let detectedVersion = '8.4.19';
  let detectedRelease = '8.4';
  let primaryNodeName = fallbackNodeName || 'informatika';
  let clusterUnbackedUp = 0;

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    if (trimmed.startsWith('# HELP ')) {
      const parts = trimmed.substring(7).split(' ');
      const mName = parts[0];
      const help = parts.slice(1).join(' ');
      metricHelps[mName] = help;
      continue;
    }

    if (trimmed.startsWith('# TYPE ')) {
      const parts = trimmed.substring(7).split(' ');
      const mName = parts[0];
      const type = parts[1] || 'gauge';
      metricTypes[mName] = type;
      continue;
    }

    if (trimmed.startsWith('#')) continue;

    // Parse metric line: metric_name{labels} value
    const match = trimmed.match(/^([a-zA-Z_:][a-zA-Z0-9_:]*)\s*(\{[^}]*\})?\s+([^\s]+)/);
    if (!match) continue;

    const metricName = match[1];
    const rawLabels = match[2] || '';
    const rawValue = match[3];
    const val = parseFloat(rawValue);

    metricCounts[metricName] = (metricCounts[metricName] || 0) + 1;

    // Parse labels into key-value map
    const labels: Record<string, string> = {};
    if (rawLabels) {
      const inside = rawLabels.slice(1, -1);
      const labelMatches = inside.matchAll(/([a-zA-Z_][a-zA-Z0-9_]*)=(?:"([^"\\]*(?:\\.[^"\\]*)*)"|([a-zA-Z0-9_.-]+))/g);
      for (const lm of labelMatches) {
        labels[lm[1]] = lm[2] !== undefined ? lm[2] : lm[3];
      }
    }

    // 1. Version Info
    if (metricName === 'pve_version_info') {
      if (labels.version) detectedVersion = labels.version;
      if (labels.release) detectedRelease = labels.release;
    }

    // 2. Node Info
    if (metricName === 'pve_node_info') {
      const nodeName = labels.name || (labels.id ? labels.id.replace('node/', '') : primaryNodeName);
      primaryNodeName = nodeName;
      const n = nodesMap.get(nodeName) || { name: nodeName, status: 'online', loadAverage: [1.1, 0.9, 0.7] };
      n.release = detectedRelease;
      n.version = detectedVersion;
      nodesMap.set(nodeName, n);
    }

    // 3. Backup summary
    if (metricName === 'pve_not_backed_up_total') {
      clusterUnbackedUp = val || 0;
    }

    // 4. Guest Info (pve_guest_info)
    if (metricName === 'pve_guest_info') {
      const id = labels.id; // e.g. "qemu/100"
      if (id) {
        const vmid = parseInt(id.split('/')[1]) || 100;
        const gType = id.startsWith('lxc') ? 'lxc' : 'qemu';
        const vm = vmsMap.get(id) || {
          vmid,
          name: labels.name || `VM-${vmid}`,
          type: gType,
          node: labels.node || primaryNodeName,
          status: 'running',
          cpuPercent: 0,
          maxCpu: 4,
          memBytes: 0,
          maxMemBytes: 4 * 1024 * 1024 * 1024,
          diskBytes: 0,
          maxDiskBytes: 32 * 1024 * 1024 * 1024,
          netInBytes: 0,
          netOutBytes: 0,
          uptimeSeconds: 0,
        };
        vm.name = labels.name || vm.name;
        vm.node = labels.node || vm.node;
        vm.tags = labels.tags || '';
        vmsMap.set(id, vm);
      }
    }

    // 5. Storage Info (pve_storage_info)
    if (metricName === 'pve_storage_info') {
      const id = labels.id; // e.g. "storage/informatika/local-lvm"
      if (id) {
        const parts = id.split('/');
        const nodeFromId = parts.length >= 3 ? parts[1] : primaryNodeName;
        const storageFromId = parts.length >= 3 ? parts.slice(2).join('/') : id.split('/').pop() || 'storage';
        const st = storagesMap.get(id) || {
          id,
          storage: labels.storage || storageFromId,
          node: labels.node || nodeFromId,
          plugintype: labels.plugintype || 'dir',
          content: labels.content || '',
          sizeBytes: 0,
          usageBytes: 0,
          shared: false,
          status: 'online',
        };
        if (labels.storage) st.storage = labels.storage;
        if (labels.node) st.node = labels.node;
        if (labels.plugintype) st.plugintype = labels.plugintype;
        if (labels.content) st.content = labels.content;
        storagesMap.set(id, st);
      }
    }

    // 6. Up status (pve_up)
    if (metricName === 'pve_up') {
      const id = labels.id;
      if (id) {
        if (id.startsWith('node/')) {
          const nodeName = id.replace('node/', '');
          const n = nodesMap.get(nodeName) || { name: nodeName, status: val > 0 ? 'online' : 'offline', loadAverage: [1.1, 0.9, 0.7] };
          n.status = val > 0 ? 'online' : 'offline';
          nodesMap.set(nodeName, n);
        } else if (id.startsWith('qemu/') || id.startsWith('lxc/')) {
          const vmid = parseInt(id.split('/')[1]) || 100;
          const gType = id.startsWith('lxc') ? 'lxc' : 'qemu';
          const vm = vmsMap.get(id) || {
            vmid,
            name: `VM-${vmid}`,
            type: gType,
            node: primaryNodeName,
            status: val > 0 ? 'running' : 'stopped',
            cpuPercent: 0,
            maxCpu: 4,
            memBytes: 0,
            maxMemBytes: 4 * 1024 * 1024 * 1024,
            diskBytes: 0,
            maxDiskBytes: 32 * 1024 * 1024 * 1024,
            netInBytes: 0,
            netOutBytes: 0,
            uptimeSeconds: 0,
          };
          vm.status = val > 0 ? 'running' : 'stopped';
          vmsMap.set(id, vm);
        } else if (id.startsWith('storage/')) {
          const parts = id.split('/');
          const nodeFromId = parts.length >= 3 ? parts[1] : primaryNodeName;
          const storageFromId = parts.length >= 3 ? parts.slice(2).join('/') : id.split('/').pop() || 'storage';
          const st = storagesMap.get(id) || {
            id,
            storage: storageFromId,
            node: nodeFromId,
            plugintype: 'dir',
            content: '',
            sizeBytes: 0,
            usageBytes: 0,
            shared: false,
            status: val > 0 ? 'online' : 'offline',
          };
          st.status = val > 0 ? 'online' : 'offline';
          storagesMap.set(id, st);
        }
      }
    }

    // 7. CPU Usage & Limit
    if (metricName === 'pve_cpu_usage_ratio') {
      const id = labels.id;
      if (id?.startsWith('node/')) {
        const nodeName = id.replace('node/', '');
        const n = nodesMap.get(nodeName) || { name: nodeName, status: 'online', loadAverage: [1.1, 0.9, 0.7] };
        n.cpuPercent = Number((val * 100).toFixed(2));
        nodesMap.set(nodeName, n);
      } else if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.cpuPercent = Number((val * 100).toFixed(2));
        }
      }
    }

    if (metricName === 'pve_cpu_usage_limit') {
      const id = labels.id;
      if (id?.startsWith('node/')) {
        const nodeName = id.replace('node/', '');
        const n = nodesMap.get(nodeName) || { name: nodeName, status: 'online', loadAverage: [1.1, 0.9, 0.7] };
        n.cpuCores = Math.round(val);
        nodesMap.set(nodeName, n);
      } else if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.maxCpu = Math.round(val);
        }
      }
    }

    // 8. Memory Size & Usage
    if (metricName === 'pve_memory_size_bytes') {
      const id = labels.id;
      if (id?.startsWith('node/')) {
        const nodeName = id.replace('node/', '');
        const n = nodesMap.get(nodeName) || { name: nodeName, status: 'online', loadAverage: [1.1, 0.9, 0.7] };
        n.maxMemBytes = Math.round(val);
        nodesMap.set(nodeName, n);
      } else if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.maxMemBytes = Math.round(val);
        }
      }
    }

    if (metricName === 'pve_memory_usage_bytes') {
      const id = labels.id;
      if (id?.startsWith('node/')) {
        const nodeName = id.replace('node/', '');
        const n = nodesMap.get(nodeName) || { name: nodeName, status: 'online', loadAverage: [1.1, 0.9, 0.7] };
        n.memBytes = Math.round(val);
        nodesMap.set(nodeName, n);
      } else if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.memBytes = Math.round(val);
        }
      }
    }

    // 9. Disk Size & Usage
    if (metricName === 'pve_disk_size_bytes') {
      const id = labels.id;
      if (id?.startsWith('node/')) {
        const nodeName = id.replace('node/', '');
        const n = nodesMap.get(nodeName) || { name: nodeName, status: 'online', loadAverage: [1.1, 0.9, 0.7] };
        n.maxDiskBytes = Math.round(val);
        nodesMap.set(nodeName, n);
      } else if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.maxDiskBytes = Math.round(val);
        }
      } else if (id?.startsWith('storage/')) {
        const st = storagesMap.get(id);
        if (st) {
          st.sizeBytes = Math.round(val);
        }
      }
    }

    if (metricName === 'pve_disk_usage_bytes') {
      const id = labels.id;
      if (id?.startsWith('node/')) {
        const nodeName = id.replace('node/', '');
        const n = nodesMap.get(nodeName) || { name: nodeName, status: 'online', loadAverage: [1.1, 0.9, 0.7] };
        n.diskBytes = Math.round(val);
        nodesMap.set(nodeName, n);
      } else if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.diskBytes = Math.round(val);
        }
      } else if (id?.startsWith('storage/')) {
        const st = storagesMap.get(id);
        if (st) {
          st.usageBytes = Math.round(val);
        }
      }
    }

    // 10. Network I/O
    if (metricName === 'pve_network_transmit_bytes_total' || metricName === 'pve_network_transmit_bytes') {
      const id = labels.id;
      if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.netOutBytes = Math.round(val);
        }
      }
    }

    if (metricName === 'pve_network_receive_bytes_total' || metricName === 'pve_network_receive_bytes') {
      const id = labels.id;
      if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.netInBytes = Math.round(val);
        }
      }
    }

    // 11. Disk I/O
    if (metricName === 'pve_disk_written_bytes_total' || metricName === 'pve_disk_write_bytes') {
      const id = labels.id;
      if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.diskWriteBytes = Math.round(val);
        }
      }
    }

    if (metricName === 'pve_disk_read_bytes_total' || metricName === 'pve_disk_read_bytes') {
      const id = labels.id;
      if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.diskReadBytes = Math.round(val);
        }
      }
    }

    // 12. Uptime seconds
    if (metricName === 'pve_uptime_seconds') {
      const id = labels.id;
      if (id?.startsWith('node/')) {
        const nodeName = id.replace('node/', '');
        const n = nodesMap.get(nodeName) || { name: nodeName, status: 'online', loadAverage: [1.1, 0.9, 0.7] };
        n.uptimeSeconds = Math.round(val);
        nodesMap.set(nodeName, n);
      } else if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.uptimeSeconds = Math.round(val);
        }
      }
    }

    // 13. Onboot Status
    if (metricName === 'pve_onboot_status') {
      const id = labels.id;
      if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.onboot = val > 0;
        }
      }
    }

    // 14. Not backed up info
    if (metricName === 'pve_not_backed_up_info') {
      const id = labels.id;
      if (id?.startsWith('qemu/') || id?.startsWith('lxc/')) {
        const vm = vmsMap.get(id);
        if (vm) {
          vm.notBackedUp = val > 0;
        }
      }
    }

    // 15. Storage shared
    if (metricName === 'pve_storage_shared') {
      const id = labels.id;
      const st = storagesMap.get(id);
      if (st) {
        st.shared = val > 0;
      }
    }
  }

  // Ensure default node exists if none parsed
  if (nodesMap.size === 0) {
    nodesMap.set(primaryNodeName, {
      name: primaryNodeName,
      status: 'online',
      cpuPercent: 1.2,
      cpuCores: 32,
      memBytes: 23111766016,
      maxMemBytes: 33547079680,
      diskBytes: 17207816192,
      maxDiskBytes: 100861726720,
      uptimeSeconds: 3125578,
      loadAverage: [0.85, 0.72, 0.65],
      release: detectedRelease,
      version: detectedVersion,
      unbackedUpTotal: clusterUnbackedUp,
    });
  }

  const nodesList: ProxmoxNode[] = Array.from(nodesMap.values()).map((n) => ({
    name: n.name || primaryNodeName,
    status: n.status || 'online',
    cpuPercent: n.cpuPercent !== undefined ? n.cpuPercent : 1.5,
    cpuCores: n.cpuCores || 32,
    memBytes: n.memBytes || 24 * 1024 * 1024 * 1024,
    maxMemBytes: n.maxMemBytes || 32 * 1024 * 1024 * 1024,
    diskBytes: n.diskBytes || 18 * 1024 * 1024 * 1024,
    maxDiskBytes: n.maxDiskBytes || 100 * 1024 * 1024 * 1024,
    uptimeSeconds: n.uptimeSeconds || 3125578,
    loadAverage: n.loadAverage || [0.85, 0.72, 0.65],
    release: n.release || detectedRelease,
    version: n.version || detectedVersion,
    unbackedUpTotal: clusterUnbackedUp,
  }));

  const vmsList: ProxmoxVm[] = Array.from(vmsMap.values()).map((v) => ({
    vmid: v.vmid || 100,
    name: v.name || `VM-${v.vmid || 100}`,
    type: v.type || 'qemu',
    node: v.node || primaryNodeName,
    status: v.status || 'running',
    cpuPercent: v.cpuPercent !== undefined ? v.cpuPercent : 0.5,
    maxCpu: v.maxCpu || 4,
    memBytes: v.memBytes || 2 * 1024 * 1024 * 1024,
    maxMemBytes: v.maxMemBytes || 4 * 1024 * 1024 * 1024,
    diskBytes: v.diskBytes || 0,
    maxDiskBytes: v.maxDiskBytes || 100 * 1024 * 1024 * 1024,
    netInBytes: v.netInBytes || 0,
    netOutBytes: v.netOutBytes || 0,
    uptimeSeconds: v.uptimeSeconds || 0,
    tags: v.tags || '',
    onboot: v.onboot !== undefined ? v.onboot : true,
    notBackedUp: v.notBackedUp !== undefined ? v.notBackedUp : true,
    diskReadBytes: v.diskReadBytes || 0,
    diskWriteBytes: v.diskWriteBytes || 0,
  }));

  const storagesList: ProxmoxStorage[] = Array.from(storagesMap.values()).map((s) => ({
    id: s.id || `storage/${primaryNodeName}/local`,
    storage: s.storage || 'local',
    node: s.node || primaryNodeName,
    plugintype: s.plugintype || 'dir',
    content: s.content || 'images',
    sizeBytes: s.sizeBytes || 100 * 1024 * 1024 * 1024,
    usageBytes: s.usageBytes || 17 * 1024 * 1024 * 1024,
    shared: Boolean(s.shared),
    status: s.status || 'online',
  }));

  // Build metric definitions array
  const metricDefinitions = Object.keys(metricCounts).map((key) => ({
    metric: key,
    help: metricHelps[key] || 'No description provided',
    type: metricTypes[key] || 'gauge',
    count: metricCounts[key] || 0,
  }));

  return {
    nodes: nodesList,
    vms: vmsList,
    storages: storagesList,
    metricDefinitions,
    rawText,
    clusterName: `Cluster ${primaryNodeName} (PVE ${detectedRelease})`,
  };
}
